export type Support = 'supported' | 'unsupported' | 'unknown';
export type MediaPath = 'http-file' | 'mse' | 'datachannel-file' | 'webrtc-rtp';
export type CodecFamily = 'avc' | 'hevc' | 'av1' | 'vp8' | 'vp9' | 'unknown';
export type AccelerationPreference = 'prefer-hardware' | 'prefer-software' | 'no-preference';
export type HardwareExecution = 'confirmed-hardware' | 'confirmed-software' | 'unknown';
export type MediaEnvironment = Record<string, any>;
export interface CodecEvidence {
  support: Support;
  preference: AccelerationPreference;
  execution: HardwareExecution;
  configuration?: VideoDecoderConfig | VideoEncoderConfig;
  reason?: string;
}
export interface ThroughputEvidence {
  frames: number; elapsedMs: number; fps: number; targetFps: number;
  codecString: string; width: number; height: number;
}
export interface CodecCandidate {
  codec: CodecFamily;
  codecString: string;
  playback: Support;
  transport: Support;
  decode: Support;
  encode: Support;
  preference: AccelerationPreference;
  execution: HardwareExecution;
  remote?: boolean;
  width?: number;
  height?: number;
  fps?: number;
  performance?: ThroughputEvidence;
}
export interface BoundedMediaSource {
  readonly identity: string;
  readonly size?: number;
  readonly nativeUrl?: string;
  read(start: number, endExclusive: number, signal?: AbortSignal): Promise<Uint8Array<ArrayBuffer>>;
  close(): void;
}
export interface MediaTrackInfo {
  id: number;
  kind: 'video' | 'audio' | 'text' | 'other';
  codec: string;
  family: CodecFamily;
  width?: number;
  height?: number;
  sampleRate?: number;
  channels?: number;
  timescale: number;
  duration: number;
  description?: Uint8Array<ArrayBuffer>;
  encrypted: boolean;
}
export interface MediaFormat {
  container: 'mp4' | 'quicktime' | 'webm' | 'matroska' | 'unknown';
  tracks: MediaTrackInfo[];
  duration?: number;
  fragmented?: boolean;
  mime?: string;
}

export const MEDIA_LIMITS = Object.freeze({
  readBytes: 1024 * 1024, metadataBytes: 16 * 1024 * 1024, indexSamples: 250000,
  frames: 4, rawFrameBytes: 64 * 1024 * 1024, encodedBytes: 8 * 1024 * 1024,
  bufferAheadSeconds: 8, bufferBehindSeconds: 4, operationTimeoutMs: 10000,
});

export function abortError() { return new DOMException('Media operation cancelled', 'AbortError'); }
export function validNumber(value: unknown, minimum = 0): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= minimum;
}

/** Race an operation without retaining cancellation listeners after completion. */
export function cancellable<T>(operation: PromiseLike<T>, signal?: AbortSignal, timeoutMs: number = MEDIA_LIMITS.operationTimeoutMs): Promise<T> {
  if (signal?.aborted) {
    void Promise.resolve(operation).catch(() => {});
    return Promise.reject(signal.reason || abortError());
  }
  return new Promise<T>((resolve, reject) => {
    const cleanup = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort); };
    const finish = (callback: (value: any) => void, value: any) => { cleanup(); callback(value); };
    const abort = () => finish(reject, signal?.reason || abortError());
    const timer = setTimeout(() => finish(reject, new DOMException('Media operation timed out', 'TimeoutError')), timeoutMs);
    signal?.addEventListener('abort', abort, { once: true });
    Promise.resolve(operation).then(value => finish(resolve, value), error => finish(reject, error));
    if (signal?.aborted) abort();
  });
}

/** A third-party transform may finish after cancellation; release its late result. */
export function cancellableFrame(operation: Promise<VideoFrame>, signal: AbortSignal) {
  return cancellable(operation.then(frame => {
    if (signal.aborted) { frame.close(); signal.throwIfAborted(); }
    return frame;
  }), signal);
}

export async function waitUntil(ready: () => boolean, signal?: AbortSignal, timeoutMs: number = MEDIA_LIMITS.operationTimeoutMs) {
  const deadline = performance.now() + timeoutMs;
  while (!ready()) {
    signal?.throwIfAborted();
    if (performance.now() >= deadline) throw new DOMException('Media queue timed out', 'TimeoutError');
    await cancellable(new Promise<void>(resolve => setTimeout(resolve, 4)), signal, timeoutMs);
  }
  signal?.throwIfAborted();
}
